namespace ghidra.app.plugin.core.search;

using docking.widgets.search;
using generic.json;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.listing;

/**
 * A simple class that represents text found in Decompiler output.
 */
public class TextMatch {

	private Function function;
	private AddressSet addresses;
	private SearchLocationContext context;
	private int lineNumber;

	private string searchText;
	private bool isMultiLine;

	TextMatch(Function function, AddressSet addresses, int lineNumber, string searchText,
			SearchLocationContext context, bool isMultiLine) {
		this.function = function;
		this.addresses = addresses;
		this.lineNumber = lineNumber;
		this.searchText = searchText;
		this.context = context;
		this.isMultiLine = isMultiLine;
	}

	public Function getFunction() {
		return function;
	}

	public SearchLocationContext getContext() {
		return context;
	}

	public int getLineNumber() {
		return lineNumber;
	}

	public Address getAddress() {
		if (addresses.isEmpty()) {
			return function.getEntryPoint();
		}

		return addresses.getFirstRange().getMinAddress();
	}

	public bool isMultiLine() {
		return isMultiLine;
	}

	public string getSearchText() {
		return searchText;
	}

	/* @Override */
	public string toString() {
		return Json.toString(this, "function", "context", "searchText");
	}
}
